insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('avatars','avatars',true,2097152,array['image/jpeg','image/png','image/webp']),('memories','memories',true,8388608,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "member image uploads" on storage.objects for insert to authenticated with check (bucket_id in ('avatars','memories') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "member image updates" on storage.objects for update to authenticated using (bucket_id in ('avatars','memories') and owner_id=(select auth.uid())::text) with check ((storage.foldername(name))[1]=(select auth.uid())::text);
create policy "member image deletes" on storage.objects for delete to authenticated using (bucket_id in ('avatars','memories') and owner_id=(select auth.uid())::text);

